import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.CRkTBNIT.js";const h=JSON.parse('{"title":"Step 2.5: Project Pitch (30-Second & 2-Minute Spoken Scripts)","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),n={name:"00b-project-pitch.md"};function o(s,e,c,d,l,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="step-2-5-project-pitch-30-second-2-minute-spoken-scripts" tabindex="-1">Step 2.5: Project Pitch (30-Second &amp; 2-Minute Spoken Scripts) <a class="header-anchor" href="#step-2-5-project-pitch-30-second-2-minute-spoken-scripts" aria-label="Permalink to &quot;Step 2.5: Project Pitch (30-Second &amp; 2-Minute Spoken Scripts)&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built an enterprise-grade omnichannel notification delivery platform using Python, FastAPI, and React that handles mission-critical alerts across Email, SMS, Push, and Webhooks. It features prioritized queues that ensure two-factor authentication codes bypass marketing blasts, automated provider fallback routing that swaps degraded vendors within 50 milliseconds, and an intelligent quiet-hours engine that suppresses non-urgent alerts during recipient nighttime.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;In distributed platforms, notification delivery is inherently brittle because it depends on third-party provider APIs like SendGrid or Twilio that experience intermittent outages, rate limits, and network latency spikes. Furthermore, marketing bulk broadcasts can easily starve urgent transactional OTPs.</p><p>To solve this, I designed and built <strong>OmniPost</strong>, a resilient notification delivery platform.</p><p>First, in <code>backend/src/queues/dispatcher.py</code>, the system implements a strict Multi-Tier Priority Queue with four priority tiers: URGENT, HIGH, NORMAL, and LOW. Critical authentication OTPs and security alerts enter with a priority weight of 100 and preempt background marketing newsletters, guaranteeing sub-second dispatch latency regardless of queue depth. To prevent low-priority jobs from starving indefinitely, the queue incorporates aging thresholds.</p><p>Second, to insulate the platform against third-party provider outages, I built an automated Provider Selection and Fallback Engine in <code>backend/src/channels/selection.py</code>. When an upstream provider returns HTTP 5xx errors or connection timeouts, the system automatically shifts traffic to a secondary failover provider (such as AWS SES or Vonage) deterministically based on health and cost without dropping messages.</p><p>Third, for failed messages, the system implements exponential backoff retries with full jitter in <code>backend/src/retries/failure.py</code>. Messages that exhaust their retry budget are routed to a Dead-Letter Queue with automated manual redrive and replay capabilities, generating new delivery attempts and immutable audit records.</p><p>Fourth, an intelligent Preference Routing Engine in <code>backend/src/preferences/routing.py</code> respects user quiet hours based on their local timezone—handling overnight wrap-around windows and Daylight Saving Time adjustments—while enforcing rolling 24-hour frequency capping.</p><p>The administrative console provides real-time visibility into queue depth, provider health, and delivery logs. The platform is backed by 114 automated tests running via <code>pytest</code>.&quot;</p></blockquote>',6)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
